import officeMap from '../../../data/maps/office-v2.json' with { type: 'json' };
import type { MapData, Tile, ZoneDef, ZoneId } from '@escape/contracts';

/** The current office map (data/maps/<DEFAULT_MAP_ID>.json, generated by data/maps/build-map.ts). */
export function loadMap(): MapData {
  return officeMap as unknown as MapData;
}

export const tileIndex = (map: MapData, col: number, row: number): number => row * map.cols + col;
export const inBounds = (map: MapData, col: number, row: number): boolean =>
  col >= 0 && row >= 0 && col < map.cols && row < map.rows;
export const tileKey = (t: Tile): string => `${t.col},${t.row}`;

export function zoneAt(map: MapData, col: number, row: number): ZoneId | null {
  return inBounds(map, col, row) ? map.zone[tileIndex(map, col, row)] : null;
}

export function zoneTiles(map: MapData, zone: ZoneId): Tile[] {
  const out: Tile[] = [];
  for (let r = 0; r < map.rows; r++) {
    for (let c = 0; c < map.cols; c++) if (map.zone[tileIndex(map, c, r)] === zone) out.push({ col: c, row: r });
  }
  return out;
}

export const tileDistance = (a: Tile, b: Tile): number => Math.hypot(a.col - b.col, a.row - b.row);

// ---------------------------------------------------------------------------------------------------------------
// Earshot: spoken alerts (notify) reach only people in the same room. Rooms and corridors (ZoneDef.kind) are the
// open spaces; doorway zones (doors, exits) belong to BOTH rooms they join, so someone standing in a doorway hears
// and is heard on both sides. Everything outdoors (sidewalks, assembly) is one room. Only the fire alarm reaches
// everyone.
// ---------------------------------------------------------------------------------------------------------------

export type RoomId = ZoneId | 'outside';

const roomCache = new WeakMap<MapData, Map<ZoneId, RoomId[]>>();
const kindCache = new WeakMap<MapData, Map<ZoneId, ZoneDef['kind']>>();

function baseRoom(map: MapData, zone: ZoneId): RoomId | null {
  let kinds = kindCache.get(map);
  if (!kinds) {
    kinds = new Map(map.zones.map((z) => [z.id, z.kind]));
    kindCache.set(map, kinds);
  }
  const kind = kinds.get(zone);
  if (kind === 'room' || kind === 'corridor') return zone;
  if (kind === 'outdoor' || kind === 'assembly') return 'outside';
  return null;
}

/** Rooms a zone belongs to: a room/outdoor zone → its room; a doorway zone → every room it joins (via map.zoneEdges). */
export function roomsOf(map: MapData, zone: ZoneId | null): RoomId[] {
  if (!zone) return [];
  let cache = roomCache.get(map);
  if (!cache) {
    cache = new Map();
    roomCache.set(map, cache);
  }
  const hit = cache.get(zone);
  if (hit) return hit;
  let rooms: RoomId[];
  const own = baseRoom(map, zone);
  if (own) rooms = [own];
  else {
    const set = new Set<RoomId>();
    for (const [a, b] of map.zoneEdges) {
      const other = a === zone ? b : b === zone ? a : null;
      const r = other ? baseRoom(map, other) : null;
      if (r) set.add(r);
    }
    rooms = [...set].sort();
  }
  cache.set(zone, rooms);
  return rooms;
}

/** True if people standing in these two zones can hear each other (their room sets intersect). */
export function inEarshot(map: MapData, zoneA: ZoneId | null, zoneB: ZoneId | null): boolean {
  if (!zoneA || !zoneB) return false;
  const ra = roomsOf(map, zoneA);
  if (!ra.length) return false;
  const rb = roomsOf(map, zoneB);
  return ra.some((r) => rb.includes(r));
}
